// Construit le sujet et le corps HTML de l'e-mail de confirmation d'une
// nouvelle tâche. Amélioration UNIQUEMENT visuelle et de contenu : mêmes
// données en entrée (mêmes références de nœuds), même contrat de sortie
// ([{ json: { subject, html } }]), aucune nouvelle requête réseau, aucun
// credential modifié, aucune connexion modifiée.
// N'inclut jamais de clé/secret dans le contenu envoyé.
const task = $node["Extraire la tâche"].json;

// Le nœud HTTP Request 'Récupérer le projet' interroge Supabase
// (GET /rest/v1/projects?id=eq....&select=title), qui renvoie un tableau
// JSON côté API PostgREST. n8n déballe automatiquement ce tableau : chaque
// élément devient un item séparé, donc $node["Récupérer le projet"].json
// est déjà directement l'objet { title } (et non un tableau) lorsque le
// projet est trouvé. Accéder à '.json[0]' ne fonctionnait donc jamais
// (cause du bug '📁 Non renseigné' affiché même quand le projet existe
// réellement en base). On accepte ici les deux formes possibles (objet
// unique ou tableau, selon la configuration exacte du nœud HTTP), sans
// ajouter de nouveau nœud ni modifier les connexions existantes.
const projectResult = $node["Récupérer le projet"].json;
const project = Array.isArray(projectResult) ? (projectResult[0] || {}) : (projectResult || {});

const appBaseUrl = $node["Configuration ProjectFlow"].json.APP_BASE_URL || "";

function esc(value) {
  return String(value == null ? "" : value).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}

const PRIORITY_META = {
  high: { label: "Haute", color: "#ef4444", bg: "#fee2e2" },
  medium: { label: "Moyenne", color: "#d97706", bg: "#fef3c7" },
  low: { label: "Basse", color: "#16a34a", bg: "#dcfce7" },
};
const priority = PRIORITY_META[task.task_priority] || { label: task.task_priority || "—", color: "#6b7280", bg: "#f3f4f6" };

const dueDate = task.task_due_date
  ? new Date(task.task_due_date).toLocaleDateString("fr-CA", { day: "numeric", month: "long", year: "numeric" })
  : "Non définie";

const projectTitle = project.title || "Non renseigné";

const buttonHtml = appBaseUrl
  ? '<p style="text-align:center;margin:20px 0 0;">' +
    '<a href="' + esc(appBaseUrl) + '/tasks/' + esc(task.task_id) + '" ' +
    'style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;padding:10px 22px;' +
    'border-radius:8px;font-size:13px;font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,0.08);">Voir la tâche</a>' +
    '</p>'
  : "";

const html =
  '<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Arial,sans-serif;color:#111827;max-width:520px;' +
  'margin:0 auto;background:#f9fafb;padding:20px;">' +

  // En-tête
  '<div style="text-align:center;margin-bottom:20px;">' +
  '<h1 style="font-size:20px;margin:0 0 6px;color:#111827;">🆕 ProjectFlow — Nouvelle tâche</h1>' +
  '<p style="font-size:13px;color:#6b7280;margin:0;">Une nouvelle tâche vient d\'être créée.</p>' +
  '</div>' +

  // Carte colorée selon la priorité
  '<div style="background:#ffffff;border:1px solid #e5e7eb;border-left:4px solid ' + priority.color + ';border-radius:12px;' +
  'padding:16px;margin-bottom:16px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
  '<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:10px;">' + esc(task.task_title) + '</div>' +
  '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:4px;">' +
  '<span style="display:inline-block;padding:3px 10px;border-radius:999px;font-size:11px;font-weight:600;color:' + priority.color + ';background:' + priority.bg + ';">Priorité : ' + esc(priority.label) + '</span>' +
  '<span style="display:inline-block;padding:3px 10px;border-radius:999px;font-size:11px;font-weight:600;color:#2563eb;background:#dbeafe;">📁 ' + esc(projectTitle) + '</span>' +
  '</div>' +
  '<div style="font-size:13px;color:#6b7280;margin-top:8px;">📅 Échéance : ' + esc(dueDate) + '</div>' +
  '</div>' +

  buttonHtml +

  // Message d'organisation
  '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:14px 16px;margin-top:16px;">' +
  '<p style="margin:0;font-size:13px;color:#1e3a8a;">💡 Bonne organisation ! Pensez à planifier cette tâche dès que possible.</p>' +
  '</div>' +

  // Pied de page
  '<div style="text-align:center;margin-top:24px;padding-top:16px;border-top:1px solid #e5e7eb;">' +
  '<p style="font-size:12px;color:#9ca3af;margin:0;font-weight:600;">ProjectFlow</p>' +
  '<p style="font-size:11px;color:#9ca3af;margin:6px 0 0;">Merci d\'utiliser ProjectFlow.</p>' +
  '<p style="font-size:11px;color:#9ca3af;margin:2px 0 0;">Votre assistant intelligent de gestion de projets.</p>' +
  '<p style="font-size:11px;color:#9ca3af;margin:2px 0 0;">Notification envoyée automatiquement à chaque nouvelle tâche.</p>' +
  '</div>' +

  '</div>';

return [{ json: { subject: "ProjectFlow — Nouvelle tâche créée", html } }];
